const item = $input.item.json;
const html = item.html || '';
const text = item.text || (html ? html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ') : '') || item.snippet || '';

return {
  json: {
    messageId: item.id,
    threadId: item.threadId,
    from: item.from,
    subject: item.subject,
    date: item.date,
    emailText: text.trim(),
  },
};

const item = $input.item.json;
const systemPrompt = `Você é um assistente que extrai dados estruturados de e-mails de leads interessados em comprar franquias/lojas da Cacau Show em Belém-PA, Brasil.

Leia o e-mail abaixo (remetente, assunto, data e corpo) e devolva APENAS um objeto JSON válido, sem markdown e sem texto antes ou depois, contendo exatamente estas chaves: nome, email, telefone, cidade, estado, empresa, cnpj, capital_disponivel, experiencia_empreendedorismo, motivacao, origem_provavel, mensagem_resumo, urgencia_percebida.

Regras: cnpj deve conter apenas dígitos (sem pontuação) ou null se não houver. origem_provavel deve ser um destes valores: Facebook/Instagram Ads, Google Ads, Site Cacau Show, Indicação, Portal de Franquias, Outro. urgencia_percebida deve ser: alta, media ou baixa. Nunca invente dado que não esteja no e-mail; use null quando não souber. Responda somente com o JSON.`;

const userContent = 'De: ' + item.from + '\nAssunto: ' + item.subject + '\nData: ' + item.date + '\n\nCorpo do e-mail:\n' + item.emailText;

return {
  json: {
    ...item,
    systemPrompt,
    userContent,
  },
};

const resp = $input.item.json;
const raw = (resp.content && resp.content[0] && resp.content[0].text) || '{}';
const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();

let lead;
try {
  lead = JSON.parse(cleaned);
} catch (e) {
  lead = { erro_parse: true, raw_resposta_ia: raw };
}

const prev = $('Prompt: Extração de Lead').item.json;

return {
  json: {
    ...lead,
    messageId: prev.messageId,
    threadId: prev.threadId,
    from: prev.from,
    subject: prev.subject,
    emailText: prev.emailText,
  },
};

const leadBase = $('Parsear JSON da IA (Extração)').item.json;
const current = $input.item.json;

let cnpjData = null;
if (current && current.razao_social) {
  cnpjData = {
    razao_social: current.razao_social || null,
    nome_fantasia: current.nome_fantasia || null,
    situacao_cadastral: current.descricao_situacao_cadastral || null,
    atividade_principal: current.cnae_fiscal_descricao || null,
    municipio: current.municipio || null,
    uf: current.uf || null,
    data_abertura: current.data_inicio_atividade || null,
    capital_social: current.capital_social || null,
  };
}

return {
  json: {
    ...leadBase,
    cnpjData,
  },
};

const item = $input.item.json;
const systemPrompt = `Você é consultor de vendas para o Bruno, franqueado de lojas Cacau Show em Belém-PA que está avaliando vender uma ou mais de suas franquias. Você recebeu os dados enriquecidos de um lead interessado em comprar. Use o perfil das lojas abaixo como referência (números podem estar desatualizados, nunca cite valores exatos ao lead sem confirmar antes com o Bruno).

Perfil das lojas à venda:
- Marambaia (código 9175, loja de rua): a de maior faturamento da rede, mas carrega um acordo de dívida em renegociação e histórico de atraso em boletos. Pitch: maior receita absoluta e ativo mais valioso da rede; o comprador precisa negociar a assunção ou quitação da dívida.
- Icoaraci (código 4304, loja de rua): a melhor margem da rede, sem dívida em aberto, despesa fixa proporcionalmente menor. Pitch: loja mais saudável e eficiente, menor risco, ótima porta de entrada para quem nunca teve uma franquia Cacau Show.
- Mário Covas (código 9201, dentro de supermercado): a menor loja e a única com resultado no vermelho hoje. Pitch: ticket de entrada mais baixo, mas só faz sentido para um comprador disposto a investir em giro/tráfego ou testar o modelo antes de crescer; seja transparente sobre o resultado atual.

Com base no JSON do lead a seguir, devolva APENAS um objeto JSON válido, sem markdown, contendo exatamente estas chaves: score, score_motivo, perfil_provavel, loja_recomendada, argumentos_de_venda, pontos_de_atencao, proximo_passo, rascunho_resposta_email.

Regras: score deve ser quente, morno ou frio. argumentos_de_venda e pontos_de_atencao devem ser listas de strings. loja_recomendada deve ser Marambaia, Icoaraci, Mário Covas ou 'depende do orçamento — apresentar as 3'. rascunho_resposta_email deve ser um rascunho pronto, cordial, em português, confirmando o interesse e propondo um próximo passo concreto (ex.: uma call), sem citar números financeiros sensíveis da loja. Responda somente com o JSON.`;

const userContent = JSON.stringify(item, null, 2);

return {
  json: {
    ...item,
    briefingSystemPrompt: systemPrompt,
    briefingUserContent: userContent,
  },
};

const resp = $input.item.json;
const raw = (resp.content && resp.content[0] && resp.content[0].text) || '{}';
const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();

let briefing;
try {
  briefing = JSON.parse(cleaned);
} catch (e) {
  briefing = { erro_parse: true, raw_resposta_ia: raw };
}

const lead = $('Consolidar Dados Enriquecidos').item.json;

return {
  json: {
    lead,
    briefing,
  },
};
